// ============================================================
//  v19: MARKETS & GOODS — 11 markets, 253 goods with rarities
//  Design: claude/silk-road-markets.md and claude/silk-road-goods-catalogue.md
//  Data:   src/markets_data.js (generated by tools/markets/gen_markets_js.py)
//  Loaded after econ.js: it replaces the goods list and the price/stock engine.
// ============================================================
// v19.1 economy rebalance (claude/silk-road-economy-rebalance.md, tuned with tools/markets/sim_acts.py):
//  k      price slope per 1,000 km from the nearest producer (x the size factor), inside the home market too
//  cap    ceiling as a multiple of the home price
//  budget dirhams of stock per merchant slot at a tier-2 city (x 0.6 + 0.2 x tier); units = budget / local price
//  chance odds per visit of replacing a common (rare goods turn up in any city of their market)
const RARITY = {
  c: { name: 'Common',    color: '#8a8a8a', chance: 1,    cap: 3.25, k: 1.00, budget: 750 },
  u: { name: 'Uncommon',  color: '#2e8b3a', chance: 0.40, cap: 3.9,  k: 0.95, budget: 650 },
  r: { name: 'Rare',      color: '#2f6fd0', chance: 0.50, cap: 5.2,  k: 0.95, budget: 1500 },
  e: { name: 'Epic',      color: '#8a3fc0', chance: 0.25, cap: 6.5,  k: 0.90, budget: 1500, maxQty: 3 },
  l: { name: 'Legendary', color: '#c9930a', chance: 0.08, cap: 7.8,  k: 0.85, budget: 1500, maxQty: 2 },
};
const SIZE_SLOPE = { bulky: 1.25, medium: 1, compact: 0.85 };  // bulky goods return a little more on silver
const FOREIGN_PREMIUM = 0.6, PREMIUM_KM = 1000;                 // +60% abroad, phased in over 1,000 km past the home market
const SAT_VALUE = 3000;                                         // dirhams of one good that move its price by a factor of e
// live animals walk beside the caravan: no cargo space, but they eat fodder every day
const LIVESTOCK = { arabianwarhorse: 1.1, heavenlyhorse: 1.1, whitemareofthekhan: 1.1, dalipony: 0.7, warelephant: 2.4, whiteelephant: 2.4, tigerforamenagerie: 1.0, whitegyrfalcon: 0.1 };
const RAR_ORDER = ['c', 'u', 'r', 'e', 'l'];
const GOOD_TYPES = { F: 'food', T: 'textiles', I: 'raw materials & dyes', S: 'spices, perfumes & medicines', G: 'gems & precious metals', A: 'crafts & art', N: 'animals & furs' };
const MARKETS = Object.fromEntries(MARKETS_DATA.map(m => [m.id, m]));
const MARKET_ORDER = MARKETS_DATA.map(m => m.id);
const CITY_MARKET = {}; for (const m of MARKETS_DATA) for (const c of m.cities) CITY_MARKET[c] = m.id;

// ---------- install the new goods (keep quest, special and guild goods) ----------
(function () {
  const keep = {}; for (const id in GOOD) { const g = GOOD[id]; if (g.special || g.quest || g.fac) keep[id] = g; }
  GOODS.length = 0; for (const k in GOOD) delete GOOD[k];
  for (const d of MARKET_GOODS) {
    if (d.id === 'holyoil') continue; // stays the fixed-price quest gift (always sold at Ayas, Acre and Jerusalem)
    const R = RARITY[d.rar];
    const g = Object.assign({}, d, { w: SIZES[d.size].w, cap: R.cap, slope: R.k });
    if (LIVESTOCK[g.id] != null) { g.w = 0; g.fodder = LIVESTOCK[g.id]; g.livestock = true; }
    if (/porcelain|celadon|ware\b|glass|lamp|tiles|jars|crystal/i.test(g.name)) g.fragile = true;
    GOODS.push(g); GOOD[g.id] = g;
  }
  Object.assign(GOOD, keep);
  const hd = MARKET_GOODS.find(d => d.id === 'holyoil'); Object.assign(GOOD.holyoil, { rar: 'l', m: 'mamluk', type: 'S' });
  if (hd) GOOD.holyoil.blurb = GOOD.holyoil.blurb || hd.blurb;
  for (const k in DEMAND) delete DEMAND[k];
  if (typeof CITY_DEMAND !== 'undefined') for (const k in CITY_DEMAND) delete CITY_DEMAND[k]; // the v11 relay tables are replaced by the markets
  for (const k in GOOD_GUIDE) delete GOOD_GUIDE[k];
})();

// ---------- MARKET: who sells what, and the per-visit merchant roll ----------
const MARKET = (() => {
  const M = {};
  M.of = cid => CITY_MARKET[cid];
  M.goodsOf = mid => GOODS.filter(g => g.m === mid);
  M.kind = cid => { const m = MARKETS[CITY_MARKET[cid]]; if (m && m.stars.includes(cid)) return 'market'; const c = ECON.byId()[cid]; return c && ECON.tierOf(c) >= 2 ? 'city' : 'town'; };
  M.kindName = { market: 'Market city', city: 'City', town: 'Town' };
  M.slotsText = { market: '10 goods', city: '5–7 goods', town: '3–4 goods' };
  M.isSpecialty = cid => { const m = MARKETS[CITY_MARKET[cid]]; return !!(m && m.special.includes(cid)); };
  M.isHub = cid => { const m = MARKETS[CITY_MARKET[cid]]; return !!(m && m.hub === cid); };
  M.makes = cid => GOODS.filter(g => g.m && g.prod.includes(cid)).map(g => g.id);
  // which goods of a rarity a city's merchant may carry
  M.eligible = (cid, rar) => {
    const m = MARKETS[CITY_MARKET[cid]]; if (!m) return [];
    // common, uncommon and (v19.1) rare: anywhere in the market; epic: where it's made, market cities and the capital;
    // legendary: where it's made and the capital. Producers are three times as likely to be picked (pickW).
    return GOODS.filter(g => g.m === m.id && g.rar === rar && (rar === 'c' || rar === 'u' || rar === 'r' || g.prod.includes(cid) || (rar === 'e' && m.stars.includes(cid)) || ((rar === 'e' || rar === 'l') && m.hub === cid)));
  };
  function rng(seed) { let h = 2166136261; for (let i = 0; i < seed.length; i++) { h ^= seed.charCodeAt(i); h = Math.imul(h, 16777619); } let s = h >>> 0; return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
  function pickW(list, cid, r) { if (!list.length) return null; const w = list.map(g => g.prod.includes(cid) ? 3 : 1); let t = r() * w.reduce((a, b) => a + b, 0); for (let i = 0; i < list.length; i++) { t -= w[i]; if (t <= 0) return list[i]; } return list[list.length - 1]; }
  M.slotCount = (cid, r) => { const k = M.kind(cid); return k === 'market' ? 10 : k === 'city' ? 5 + Math.floor(r() * 3) : 3 + Math.floor(r() * 2); };
  // v19.1: each slot holds about the same value of goods, so cheap goods come in big lots and dear ones in ones and twos
  M.budget = (g, cid) => RARITY[g.rar].budget * (0.6 + 0.2 * ECON.tierOf(ECON.byId()[cid]));
  M.quantity = (g, cid, r, day) => { const R = RARITY[g.rar]; let q = M.budget(g, cid) / ECON.mid(g.id, cid, day || 0) * (0.7 + 0.6 * r()); q = Math.max(1, Math.round(q)); return R.maxQty ? Math.min(R.maxQty, q) : q; };
  // roll a merchant's stock: commons fill the slots, then each rarity rolls once to replace a common
  M.roll = (s, cid, visit) => {
    const r = rng(`${(s && s.seed) || 0}|${cid}|${visit}`);
    const n = M.slotCount(cid, r); const offers = [];
    const commons = M.eligible(cid, 'c').slice(); while (offers.length < n && commons.length) { const g = pickW(commons, cid, r); commons.splice(commons.indexOf(g), 1); offers.push(g); }
    const unc = M.eligible(cid, 'u').slice(); while (offers.length < n && unc.length) { const g = pickW(unc, cid, r); unc.splice(unc.indexOf(g), 1); offers.push(g); }
    const hits = [];
    for (const rar of ['u', 'r', 'e', 'l']) {
      const el = M.eligible(cid, rar).filter(g => !offers.includes(g)); if (!el.length) continue;
      let p = RARITY[rar].chance; if ((rar === 'e' || rar === 'l') && M.isSpecialty(cid) && el.some(g => g.prod.includes(cid))) p *= 2;
      if (r() >= p) continue;
      const g = pickW(el, cid, r);
      const ci = offers.map((o, i) => [o, i]).filter(([o]) => o.rar === 'c'); const lo = ci.length ? ci[Math.floor(r() * ci.length)][1] : offers.findIndex(o => o.rar === 'u');
      if (lo >= 0 && offers.length >= n) offers.splice(lo, 1); offers.push(g); if (rar !== 'u') hits.push(g.id);
    }
    // story: Act I's trade goods are always on sale at Acre
    if (s && s.camp && (s.camp.act || 1) <= 1 && cid === 'acre') for (const id of ['rosewater', 'linen', 'sugar']) if (GOOD[id] && !offers.includes(GOOD[id])) { const ci = offers.findIndex(o => o.rar === 'c' && !['linen', 'sugar'].includes(o.id)); if (ci >= 0) offers.splice(ci, 1); offers.push(GOOD[id]); }
    offers.sort((a, b) => RAR_ORDER.indexOf(b.rar) - RAR_ORDER.indexOf(a.rar) || a.name.localeCompare(b.name));
    const max = {}; for (const g of offers) max[g.id] = M.quantity(g, cid, r, (s && s.day) || 0);
    return { offers: offers.map(g => g.id), max, hits };
  };
  // arrival: stock and contracts refresh after 3+ days away, or when the last city was another one
  M.arrive = (s, cid, prev) => {
    const st = s.stock[cid];
    const fresh = !st || !st.offers || prev !== cid || s.day - st.day >= 3;
    if (!fresh) { st.day = s.day; return []; }
    const visit = ((st && st.visit) || 0) + 1; const R = M.roll(s, cid, visit);
    s.stock[cid] = { day: s.day, visit, offers: R.offers, q: Object.assign({}, R.max), max: R.max };
    return R.hits;
  };
  // what a city usually sells (for cities the player hasn't visited yet)
  M.typical = cid => { const el = M.eligible(cid, 'c').slice().sort((a, b) => (b.prod.includes(cid) - a.prod.includes(cid)) || a.base - b.base); const k = M.kind(cid); return el.slice(0, k === 'market' ? 8 : k === 'city' ? 6 : 4).map(g => g.id); };
  // the two markets (2,000 km or more away) that pay most for a good
  M.bestMarkets = gid => {
    const g = GOOD[gid]; if (!g || !g.m || !ECON.dist[gid]) return [];
    return MARKET_ORDER.filter(o => o !== g.m).map(o => { const d = ECON.dist[gid][MARKETS[o].hub]; const dem = (MARKET_DEMAND[o] || {})[g.type] || 1; return [dem * (1 + 0.01 * Math.min(d, 8000) / 1000) - (d < 2000 ? 1 : 0), o]; }).sort((a, b) => b[0] - a[0]).slice(0, 2).map(x => x[1]);
  };
  // road km from the nearest city of a market (0 inside it)
  const mdist = {};
  M.distFromMarket = (mid, cid) => {
    if (!mdist[mid]) { const adj = ECON.adj(); const d = {}; const q = []; for (const c of MARKETS[mid].cities) if (adj[c]) { d[c] = 0; q.push(c); }
      const done = {}; for (;;) { let u = null, b = Infinity; for (const k in d) if (!done[k] && d[k] < b) { b = d[k]; u = k; } if (!u) break; done[u] = 1; for (const [v, km] of adj[u] || []) if (!(v in d) || b + km < d[v]) d[v] = b + km; }
      mdist[mid] = d; }
    const v = mdist[mid][cid]; return v == null ? 99999 : v;
  };
  M.rarName = g => RARITY[(GOOD[g] || g).rar || 'c'].name;
  M.rarColor = g => RARITY[(GOOD[g] || g).rar || 'c'].color;
  M.rarClass = g => 'rar-' + ((GOOD[g] || g).rar || 'c');
  return M;
})();

// ---------- prices ----------
(function () {
  const mid0 = ECON.mid; // still used for the guild goods, which have no market
  function hash(a, b, c) { let h = 2166136261; for (const s of [a, b, String(c), String(ECON.seed || 0)]) for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0) / 4294967296; }
  function drift(cid, gid, day) { const t = day / 45; const k = Math.floor(t), f = t - k; const a = hash(cid, gid, k), b = hash(cid, gid, k + 1); const s = f * f * (3 - 2 * f); return 0.88 + 0.24 * (a + (b - a) * s); }
  // v19.1: the price climbs with road distance from where the good is made, inside its own market too (so border
  // cities are not free gateways), up to the tier's ceiling. In another market it also earns the foreign premium,
  // phased in over the first 1,000 km past its home market's edge, times what that market pays extra for the
  // type of good (ceiling: the tier's ceiling x 1.15). Tuned with tools/markets/sim_acts.py to the pace of Acts I-III.
  ECON.priceMult = (gid, cid) => {
    const g = GOOD[gid]; const R = RARITY[g.rar]; const mk = CITY_MARKET[cid];
    const d = ECON.dist[gid][cid]; const k = R.k * (SIZE_SLOPE[g.size] || 1);
    if (mk === g.m || !mk) return Math.min(R.cap, 1 + k * d / 1000);
    const ramp = Math.min(1, MARKET.distFromMarket(g.m, cid) / PREMIUM_KM);
    const m = Math.min(R.cap, 1 + FOREIGN_PREMIUM * ramp + k * d / 1000);
    const dem = (MARKET_DEMAND[mk] || {})[g.type] || 1; return Math.min(R.cap * 1.15, m * dem);
  };
  // v19.1: saturation counts silver, not units, so a pouch of rubies moves a market as much as a cartload of grain
  const elast0 = ECON.elast;
  ECON.elast = (gid, cid) => {
    const g = GOOD[gid]; if (!g || !g.m) return elast0(gid, cid);
    const c = ECON.byId()[cid]; const day = (ECON.state && ECON.state.day) || 0;
    return SAT_VALUE * (0.6 + 0.2 * ECON.tierOf(c)) / Math.max(0.5, ECON.mid(gid, cid, day));
  };
  ECON.mid = function (gid, cid, day) {
    const g = GOOD[gid]; if (!g) return 0;
    if (g.special) return g.base;
    if (!g.m) return mid0(gid, cid, day);
    const c = ECON.byId()[cid];
    return g.base * ECON.priceMult(gid, cid) * (1 + 0.04 * (ECON.tierOf(c) - 2)) * drift(cid, gid, day);
  };
  ECON.offers = function (cid) {
    const s = ECON.state; let st = s && s.stock && s.stock[cid];
    // the city the player is standing in (e.g. Acre at the start of the story) rolls its stock on first look
    if (s && s.stock && (!st || !st.offers) && cid === s.lastCity) { MARKET.arrive(s, cid, cid); st = s.stock[cid]; }
    const out = st && st.offers ? st.offers.filter(g => GOOD[g]) : MARKET.typical(cid);
    if (cid === 'ayas' || cid === 'jerusalem' || cid === 'acre') out.push('holyoil');
    return out;
  };
  ECON.stockMax = (gid, cid) => {
    const g = GOOD[gid]; if (!g || g.special) return 1;
    const s = ECON.state; const st = s && s.stock && s.stock[cid];
    if (st && st.max && st.max[gid] != null) return st.max[gid];
    if (!g.m) { const t = ECON.tierOf(ECON.byId()[cid]); return Math.round((10 + t * 8) / Math.max(0.3, g.w)); }
    const R = RARITY[g.rar]; const q = Math.max(1, Math.round(MARKET.budget(g, cid) / ECON.mid(gid, cid, (s && s.day) || 0))); return R.maxQty ? Math.min(R.maxQty, q) : q;
  };
})();

// ---------- the Goods guide ----------
(function () {
  const guide0 = goodGuide;
  goodGuide = function (gid) {
    if (GOOD_GUIDE[gid]) return GOOD_GUIDE[gid];
    const g = GOOD[gid]; if (!g || !g.m || g.special) return guide0(gid);
    const byId = ECON.byId(); const src = g.prod.filter(p => byId[p]).map(p => byId[p].name.replace(/ \(.*\)/, ''));
    const best = MARKET.bestMarkets(gid).map(o => MARKETS[o].name);
    return GOOD_GUIDE[gid] = { made: `${src.join(', ')} (${MARKETS[g.m].name})`, best: best.join(', '), bestCities: [], mult: RARITY[g.rar].cap, market: g.m };
  };
})();

// ---------- icons: template drawings for the new goods ----------
(function () {
  if (typeof ICONS === 'undefined' || !ICONS.T) return;
  const T = ICONS.T, I = ICONS.I, st = T.st;
  const NAMED = [[/ruby|coral|crimson|scarlet|red|blood|carnelian|cinnabar|madder|sappan/i, '#b8322a', '#f0a090'], [/gold|golden|saffron|turmeric|wars|amber|honey|ghee|gur|sugar candy/i, '#d8a832', '#f8e090'],
    [/silver|tin|iron|steel|salt|natron|alabaster|white|ivory|mammoth|walrus|ermine|bear|mare|elephant|paper|samite|linen|muslin|calico/i, '#e6e2d6', '#ffffff'], [/black|coal|ebony|ink|shark|bonito|sturgeon|naphtha/i, '#3a342e', '#7a6e62'],
    [/lapis|indigo|sapphire|turquoise|blue|qingbai|kingfisher/i, '#2c5fa8', '#a8c8f0'], [/jade|emerald|celadon|green|pistachio|tea|henna|betel|cardamom|myrobalan|senna/i, '#5a9a5a', '#c8f0c8'],
    [/purple|kermes|lac\b|sticklac|plum/i, '#7a2a6a', '#d8a0d0'], [/copper|bronze|brass|cassia|cinnamon|cattle|hides|leather|goatskins|teak|timber|sandal|walnut|hazelnut/i, '#a8683a', '#e8b080']];
  const PAL = { F: ['#b8925a', '#e8c890'], T: ['#c86a3a', '#f0c098'], I: ['#8a7a5a', '#d8c8a0'], S: ['#a85a2a', '#f0b878'], G: ['#3a8aa8', '#b8e8f8'], A: ['#b08a3a', '#f0d890'], N: ['#7a5a3a', '#c8a078'] };
  const col = g => { for (const [re, a, b] of NAMED) if (re.test(g.name)) return [a, b]; return PAL[g.type] || PAL.A; };
  const book = (c) => `<path d="M10 14 q7 -3 14 0 v22 q-7 -3 -14 0 z" fill="#f4ecd4" ${st}/><path d="M24 14 q7 -3 14 0 v22 q-7 -3 -14 0 z" fill="#f4ecd4" ${st}/><path d="M9 15 v23 q8 -3 15 0 q7 -3 15 0 v-23" fill="none" stroke="${c}" stroke-width="2.2"/><path d="M13 19 h8 M13 23 h8 M27 19 h8 M27 23 h8" stroke="#8a7a5a" stroke-width="1"/>`;
  const figure = (c, hi) => `<path d="M17 38 h14 l-2 -4 h-10 z" fill="#6a4a2a" ${st}/><path d="M24 10 q4 0 4 4 q0 3 -2 4 q6 2 7 9 l-3 1 l-1 -4 l0 9 h-10 l0 -9 l-1 4 l-3 -1 q1 -7 7 -9 q-2 -1 -2 -4 q0 -4 4 -4 z" fill="${c}" ${st}/><path d="M22 14 q2 -2 4 0" stroke="${hi}" fill="none" stroke-width="1.2"/>`;
  const vase = (c, band) => `<path d="M19 9 h10 v4 q9 5 8 14 q-1 11 -13 12 q-12 -1 -13 -12 q-1 -9 8 -14 z" fill="${c}" ${st}/><path d="M14 24 q10 4 20 0" fill="none" stroke="${band}" stroke-width="1.8"/><path d="M19 15 q2 2 4 1" stroke="#fff" stroke-opacity=".7" fill="none" stroke-width="1.4"/>`;
  const animal = (c) => `<path d="M14 38 q-2 -10 4 -16 l-4 -9 l6 5 q3 -3 7 -3 l5 -5 l1 6 q5 4 5 11 q0 4 -3 6 l-3 -1 q-1 -3 -4 -3 q-3 3 -3 9 z" fill="${c}" ${st}/><circle cx="30" cy="20" r="1.4" fill="#1a1410"/>`;
  const pelt = (c, hi) => `<path d="M10 22 q3 -8 10 -6 q4 -3 8 0 q7 -2 10 6 q-2 4 -1 9 q-6 6 -13 6 q-7 0 -13 -6 q1 -5 -1 -9 z" fill="${c}" ${st}/><path d="M14 24 l2 3 M20 22 l1 4 M27 22 l-1 4 M33 24 l-2 3 M18 30 l2 2 M28 30 l-2 2" stroke="${hi}" stroke-width="1.4"/>`;
  const log = (c, hi) => `<rect x="9" y="19" width="30" height="11" rx="5.5" fill="${c}" ${st}/><ellipse cx="9.5" cy="24.5" rx="3" ry="5.5" fill="${hi}" ${st}/><circle cx="9.5" cy="24.5" r="2" fill="none" stroke="#3a2614" stroke-width=".8"/>`;
  const ingot = (c, hi) => `<path d="M10 28 l6 -8 h18 l4 8 z" fill="${c}" ${st}/><path d="M10 28 h28 v5 h-28 z" fill="${c}" ${st}/><path d="M18 22 h12" stroke="${hi}" stroke-width="1.4"/>`;
  const crate = (c, hi) => `<rect x="10" y="15" width="28" height="20" rx="1" fill="#b8925a" ${st}/><path d="M10 22 h28 M10 29 h28 M17 15 v20 M31 15 v20" stroke="#7a5a32" stroke-width="1"/><circle cx="24" cy="25" r="5" fill="${c}" ${st}/><path d="M22 23 q2 -1 4 0" stroke="${hi}" fill="none"/>`;
  const blade = (c, hi) => `<path d="M14 36 l18 -24 l3 2 l-17 25 z" fill="${c}" ${st}/><path d="M17 33 q4 -3 3 -6 M22 27 q4 -3 3 -6" fill="none" stroke="${hi}" stroke-width=".9"/><path d="M11 33 l9 6 M13 36 l-3 4" stroke="#6a4a2a" stroke-width="3"/>`;
  const draw = g => {
    const [c, hi] = col(g); const u = g.unit, n = g.name;
    if (/sword|steel|bows/i.test(n)) return blade(c, hi);
    if (u === 'bolt') return T.bolt(c, hi);
    if (u === 'jar') return T.jar(c);
    if (u === 'head') return animal(c);
    if (u === 'volume') return book(g.rar === 'l' || g.rar === 'e' ? '#c9930a' : '#8a2a24');
    if (u === 'log') return log(c, hi);
    if (u === 'ingot') return ingot(c, hi);
    if (u === 'crate') return /porcelain|celadon|ware|jars|lamp|bowl/i.test(n) ? vase(c, '#2c5fa8') : crate(c, hi);
    if (u === 'roll') return I.carpets ? I.carpets() : crate(c, hi);
    if (u === 'piece') return /icon|statue|bronze|buddha|figure/i.test(n) ? figure(c, hi) : /ewer|lamp|bowl|plate/i.test(n) ? vase(c, hi) : /globe|astrolabe/i.test(n) ? `<circle cx="24" cy="24" r="12" fill="${c}" ${st}/><path d="M12 24 h24 M24 12 v24 M15 17 q9 6 18 0 M15 31 q9 -6 18 0" fill="none" stroke="#3a2614" stroke-width="1"/>` : crate(c, hi);
    if (g.type === 'N') return pelt(c, hi);
    if (g.type === 'G') return /dust|gold|silver|bars|sommo/i.test(n) ? T.nuggets(c, hi) : /pearl|beads/i.test(n) ? T.beads(c, hi) : T.gems(c, hi, 3);
    if (u === 'pouch' && g.type === 'S') return T.flask(c, hi);
    if (u === 'cake') return `<rect x="12" y="16" width="24" height="16" rx="2" fill="${c}" ${st}/><rect x="15" y="12" width="18" height="5" rx="1" fill="${hi}" ${st}/>`;
    return T.sack(c, true, hi);
  };
  for (const g of GOODS) if (!I[g.id]) I[g.id] = () => draw(g);
})();
